{
  "name": "HDAWG 任意波形发生器",
  "name_en": "HDAWG Arbitrary Waveform Generator",
  "manufacturer": "Zurich Instruments",
  "description": "Zurich Instruments 的 HDAWG 高密度任意波形发生器，用于实验中输出高速可编程模拟波形，并通过外部参考时钟、AWG 通道和 DIO/码字接口与其他设备同步。该驱动包含默认设置加载、外部时钟确认、实时波形上传以及 DIO/AWG 调试可视化等功能，常用于量子控制等精密时序实验。",
  "description_en": "The Zurich Instruments HDAWG is a high-density arbitrary waveform generator used to produce high-speed programmable analog waveforms and synchronize with other instruments via an external reference clock, AWG channels, and DIO/codeword interfaces. This driver supports loading default settings, ensuring external clocking, real-time waveform upload, and DIO/AWG debug visualization, commonly for precision timing applications such as quantum control.",
  "actions": [
    {
      "action_name": "auto-assure_ext_clock",
      "description": "确保仪器使用外部参考时钟并检查同步状态。",
      "description_en": "Ensure the instrument uses an external reference clock and verify its synchronization status."
    },
    {
      "action_name": "auto-load_default_settings",
      "description": "加载默认设置，使仪器进入已知状态，包括外部时钟、输出清零、AWG 清空和 DIO 参数复位。",
      "description_en": "Load default settings to bring the instrument into a known state, including external clock selection, output clearing, AWG clearing, and DIO parameter reset."
    },
    {
      "action_name": "auto-plot_awg_codewords",
      "description": "绘制 AWG 码字信息，用于检查和调试码字触发或数字控制配置。",
      "description_en": "Plot AWG codeword information for inspecting and debugging codeword triggering or digital control configuration."
    },
    {
      "action_name": "auto-plot_dio_snapshot",
      "description": "绘制 DIO 位快照，用于调试数字输入输出状态。",
      "description_en": "Plot a snapshot of DIO bits for debugging digital input/output states."
    },
    {
      "action_name": "auto-upload_waveform_realtime",
      "description": "向指定 AWG 实时上传波形数据。",
      "description_en": "Upload waveform data to a specified AWG in real time."
    },
    {
      "action_name": "auto-get_idn",
      "description": "获取设备标识信息。",
      "description_en": "Get device identification."
    }
  ],
  "tag_hints": [
    "arbitrary waveform generation",
    "Zurich Instruments HDAWG",
    "quantum control",
    "external reference clock",
    "DIO codeword triggering",
    "real-time waveform upload",
    "high-speed synchronized outputs"
  ]
}

